// Retain short straight runs; round only a small fraction of each corner.\n const round=.16,last=points[points.length-1],first=points[0];\n ctx.moveTo(mix(first.x,last.x,round),mix(first.y,last.y,round));\n points.forEach((p,i)=>{\n  const prev=points[(i+points.length-1)%points.length],next=points[(i+1)%points.length];\n  ctx.lineTo(mix(p.x,prev.x,round),mix(p.y,prev.y,round));\n  ctx.quadraticCurveTo(p.x,p.y,mix(p.x,next.x,round),mix(p.y,next.y,round));\n });ctx.closePath();\n}\n// Keep the starting membrane intact. The previous post-deformation leg\n// cap collapsed neighbouring lower vertices into a fan before legs existed.\nfunction limbMaterial(p,st){return p}\n// Local wall remodeling: fixed pore sites change aperture, not position.\nconst membraneNormals=new WeakMap();\nfunction remodelBoundary(loop,index,st){\n const p=loop[index];if(!st.living)return p;\n let data=membraneNormals.get(loop);\n if(!data){\n  let area=0;for(let i=0;i<loop.length;i++){const a=loop[i],b=loop[(i+1)%loop.length];area+=a[0]*b[1]-b[0]*a[1]}\n  const xs=loop.map(p=>p[0]),ys=loop.map(p=>p[1]);\n  const radius=Math.min(Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys))*.5;\n  const normals=loop.map((p,i)=>{const a=loop[(i+loop.length-1)%loop.length],b=loop[(i+1)%loop.length],dx=b[0]-a[0],dy=b[1]-a[1],n=Math.hypot(dx,dy)||1;return [dy/n*Math.sign(area),-dx/n*Math.sign(area)]});\n  data={normals,radius};membraneNormals.set(loop,data);\n }\n const phase=st.livePhase;\n const pulse=Math.sin(phase*1.5)*Math.sin(p[0]*.037+p[1]*.021)+.55*Math.sin(phase*2)*Math.cos(p[0]*.019-p[1]*.043);\n const isOuter=loop===A4_BOUNDARIES[0];\n const amplitude=isOuter?4.8:Math.min(4.8,data.radius*.55);\n const amount=amplitude*pulse*st.living,n=data.normals[index];\n return [p[0]+n[0]*amount,p[1]+n[1]*amount];\n}\nfunction bodyVertex(v,i,st){\n v=remodelBoundary(A4_BOUNDARIES[0],i,st);\n const a=A4_SOURCE_ANGLES[i];\n const front=(.5-.5*Math.sin(a))**2;\n const local=st.follow+(st.reach-st.follow)*.80*front;\n const source=sampleSource(V4_SOURCE.outline,sourceTop/V4_SOURCE.outline.length+(a+Math.PI/2)/TAU);\n const sx=mix(25*Math.cos(a),source.x,st.spread),sy=mix(35+25*Math.sin(a),source.y,st.spread);\n return {x:mix(sx,v[0],local),y:mix(sy,v[1],local)};\n}\n// Advect print marks with the same moving boundary/material coordinates.\n// This clipping only keeps ink out of actual openings; it does not reveal\n// a stationary texture beneath a moving silhouette.\nfunction prepareInk(st){\n const bins=1024,rim=new Array(bins),score=new Float32Array(bins);\n const loop=A4_BOUNDARIES[0];\n loop.forEach((v,i)=>{\n  const a=A4_SOURCE_ANGLES[i],bin=Math.floor(((a/TAU%1+1)%1)*bins)%bins;\n  const radius=Math.hypot(v[0],v[1]-35);\n  if(!rim[bin]||radius>score[bin]){rim[bin]=bodyVertex(v,i,st);score[bin]=radius}\n });\n const known=[];for(let i=0;i<bins;i++)if(rim[i])known.push(i);\n for(let k=0;k<known.length;k++){\n  const start=known[k],end=known[(k+1)%known.length]+(k===known.length-1?bins:0);\n  const a=rim[start],b=rim[end%bins];\n  for(let i=start+1;i<end;i++)rim[i%bins]={x:mix(a.x,b.x,(i-start)/(end-start)),y:mix(a.y,b.y,(i-start)/(end-start))};\n }\n st.inkRim=rim;\n}\nfunction materialInk(p,st){\n const f=p.angle/TAU*1024,i=Math.floor(f),a=st.inkRim[i%1024],b=st.inkRim[(i+1)%1024];\n const q={x:mix(a.x,b.x,f-i)*p.rho,y:35+(mix(a.y,b.y,f-i)-35)*p.rho};\n return livingMaterial(limbMaterial(q,st),st);\n}\n// Final-reference material rays map every opening and every neighbouring\n// membrane point through the same deformation. Hole centres have no private\n// animation or interpolation from an unrelated source slit.\nconst apertureAreas=A4_BOUNDARIES.map(loop=>loop.reduce((a,p,i)=>{const q=loop[(i+1)%loop.length];return a+p[0]*q[1]-q[0]*p[1]},0)/2);\nconst apertureRays=Array.from({length:1024},(_,k)=>{\n const a=k/1024*TAU,nx=Math.cos(a),ny=Math.sin(a),loop=A4_BOUNDARIES[0];let far=0,hit=null;\n for(let i=0;i<loop.length;i++){\n  const p=loop[i],q=loop[(i+1)%loop.length],ex=q[0]-p[0],ey=q[1]-p[1],det=nx*ey-ny*ex;\n  if(Math.abs(det)<1e-7)continue;const y=p[1]-35,t=(p[0]*ey-y*ex)/det,u=(p[0]*ny-y*nx)/det;\n  if(t>far&&u>=0&&u<=1){far=t;hit={i,j:(i+1)%loop.length,u,r:t}}\n }return hit;\n});\nfunction materialSite(point,st){\n const dx=point.x,dy=point.y-35,r=Math.hypot(dx,dy);if(r<.001)return {x:0,y:35};\n const f=((Math.atan2(dy,dx)/TAU%1+1)%1)*1024,i=Math.floor(f),j=(i+1)%1024;\n if(!st.apertureRim)st.apertureRim=new Array(1024);\n function at(k){\n  if(st.apertureRim[k])return st.apertureRim[k];\n  const ray=apertureRays[k];if(!ray)return {x:0,y:35,r:1};\n  const a=bodyVertex(A4_BOUNDARIES[0][ray.i],ray.i,st),b=bodyVertex(A4_BOUNDARIES[0][ray.j],ray.j,st);\n  return st.apertureRim[k]={x:mix(a.x,b.x,ray.u),y:mix(a.y,b.y,ray.u),r:ray.r};\n }\n const a=at(i),b=at(j),rho=r/mix(a.r,b.r,f-i);\n return {x:mix(a.x,b.x,f-i)*rho,y:35+(mix(a.y,b.y,f-i)-35)*rho};\n}\nfunction traceMaterialField(st){\n ctx.beginPath();const points=A4_BOUNDARIES[0].map((v,i)=>{\n  const p=bodyVertex(v,i,st),q=livingMaterial(p,st);return {x:450+q.x,y:450+q.y};\n });smoothContour(points);return 1;\n}\nfunction drawMaterialOpenings(st){\n const progress=st.reach*.12+st.follow*.88,pores=smooth((st.spread-.18)/.82);\n ctx.fillStyle='#000';\n for(let j=1;j<A4_BOUNDARIES.length;j++){\n  if(apertureAreas[j]>0)continue;\n  if(!document.querySelector('#mesh').checked&&j>1)continue;\n  const loop=A4_BOUNDARIES[j],c=A4_CENTERS[j];\n  if(j===1){\n   // Existing upper/lower windows widen vertically and join in place.\n   // No replacement counter or transported source-window overlay.\n   const join=st.follow;\n   for(const side of [-1,1]){\n    const points=loop.map((_,i)=>{\n     const v=remodelBoundary(loop,i,st);\n     const x=v[0]*pores;\n     const y=35+side*29*(1-join)+(v[1]-35)*mix(.27,1,join)*pores;\n     const q=livingMaterial({x,y},st);return {x:450+q.x,y:450+q.y};\n    });ctx.beginPath();smoothContour(points);ctx.fill();\n   }\n   continue;\n  }\n  // Use the same local reach/follow mixture as the surrounding outer rim.\n  // The pore rim is transported by that material, with no separate arrival clock.\n  const angle=Math.atan2(c.y-35,c.x);\n  const front=(.5-.5*Math.sin(angle))**2;\n  const strain=st.follow+(st.reach-st.follow)*.80*front;\n  const aperture=pores*(.08+.92*strain);\n  const points=loop.map((_,i)=>{\n   const v=remodelBoundary(loop,i,st);\n   const tissue=materialSite({x:c.x+(v[0]-c.x)*aperture,y:c.y+(v[1]-c.y)*aperture},st);\n   const q=livingMaterial(tissue,st);return {x:450+q.x,y:450+q.y};\n  });ctx.beginPath();smoothContour(points);ctx.fill();\n }\n // Keep reference fragments attached to the moving material.\n ctx.fillStyle='#bdbdb9';\n for(let j=1;j<A4_BOUNDARIES.length;j++){\n  if(apertureAreas[j]<0)continue;\n  const loop=A4_BOUNDARIES[j],c=A4_CENTERS[j],scale=pores*progress;\n  const points=loop.map((_,i)=>{const v=remodelBoundary(loop,i,st),p=materialSite({x:c.x+(v[0]-c.x)*scale,y:c.y+(v[1]-c.y)*scale},st);const q=livingMaterial(p,st);return {x:450+q.x,y:450+q.y}});\n  ctx.beginPath();smoothContour(points);ctx.fill();\n }\n}\nconst livingRegions=[\n {cy:0,rx:120,ry:112,delay:0,gain:1},\n {cy:-96,rx:172,ry:150,delay:.55,gain:1},\n {cy:100,rx:172,ry:150,delay:1.05,gain:1}\n];\nfunction livingMaterial(p,st){\n if(!st.living)return p;\n // One shared, gentle breath. Keep the centre anchored and avoid drift.\n const breath=.014*Math.sin(st.livePhase)*st.living;\n return {x:p.x*(1+breath),y:35+(p.y-35)*(1+breath*.85)};\n}\nfunction draw(){\n syncCanvasResolution();\n const st=state();ctx.fillStyle='#000';ctx.fillRect(0,0,900,900);\n // Match S's 511-unit reference height and centre the completed letter.\n ctx.save();ctx.translate(450,450);ctx.scale(1.190587139,1.190587139);ctx.translate(-450.000000000,-457.400000000);\n const alive=st.living>.000001;\n // One contour pipeline for growing, formed and returning tissue. Never\n // replace the generated surface with a different vector path at completion.\n traceMaterialField(st);ctx.fillStyle='#bdbdb9';ctx.fill('evenodd');\n if(document.querySelector('#surface').checked){\n  prepareInk(st);ctx.save();ctx.clip('evenodd');const inks=['rgba(12,12,12,.60)','rgba(255,255,250,.85)','rgba(45,45,43,.26)'];\n  grain.forEach((batch,index)=>{ctx.beginPath();for(const p of batch){const q=materialInk(p,st);ctx.rect(450+q.x,450+q.y,p.r,p.r*.8)}ctx.fillStyle=inks[index];ctx.fill()});ctx.restore();\n }\n drawMaterialOpenings(st);\n if(document.querySelector('#guide').checked){ctx.save();ctx.setLineDash([4,5]);ctx.beginPath();guide.forEach((p,i)=>i?ctx.lineTo(450+p.x,450+p.y):ctx.moveTo(450+p.x,450+p.y));ctx.strokeStyle='#666';ctx.lineWidth=1;ctx.stroke();ctx.restore()}\n ctx.restore();\n \n document.querySelector('#phase').textContent=st.phase;document.querySelector('#cycle').textContent='A01 / REFERENCE BAND DEFORMATION';\n document.querySelector('#timeline').value=st.t/st.total*100;document.querySelector('#timelineVal').textContent=Math.round(st.t/st.total*100)+'%';\n}\nfunction values(){ids.forEach(id=>document.getElementById(id+'Val').textContent=controls[id].value)}\nfunction pause(){paused=!paused;last=0;document.querySelector('#pause').textContent=paused?'Play':'Pause';draw()}\nfunction restart(){elapsed=0;last=0;paused=false;document.querySelector('#pause').textContent='Pause';draw()}\nids.forEach(id=>controls[id].oninput=()=>{values();draw()});\ndocument.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{presets[+b.dataset.preset].forEach((v,i)=>controls[ids[i]].value=v);values();restart()});\ndocument.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{const key=+b.dataset.stage;elapsed=key===1?0:key===2?timing().rd*.8:timing().formed+1;paused=true;last=0;document.querySelector('#pause').textContent='Play';draw()});\nfor(const id of ['guide','mesh','surface','flow','cleft'])document.querySelector('#'+id).onchange=draw;\ndocument.querySelector('#pause').onclick=pause;document.querySelector('#reset').onclick=restart;\ndocument.querySelector('#variation').onclick=()=>{seed++;generate();restart()};\ndocument.querySelector('#timeline').oninput=e=>{paused=true;last=0;elapsed=+e.target.value/100*timing().total;document.querySelector('#pause').textContent='Play';draw()};\ndocument.querySelector('#save').onclick=()=>{const a=document.createElement('a');a.download='V4_01_A01.png';a.href=canvas.toDataURL();a.click()};\ndocument.addEventListener('keydown',e=>{if(e.target.matches('input,button,select'))return;if(e.code==='Space'){e.preventDefault();pause()}if(e.key.toLowerCase()==='r')restart();if(e.key.toLowerCase()==='n')document.querySelector('#variation').onclick()});\nvalues();generate();restart();\nfunction tick(now){if(!paused){elapsed+=last?Math.min((now-last)/1000,.04)*1.11:0;draw()}last=now;requestAnimationFrame(tick)}requestAnimationFrame(tick);\n\n\n\nconst labTiming=timing();let labGrowth=1,labRelease=0;\nconst labNativeState=state;\nstate=function(){const st=labNativeState();const reach=labGrowth,follow=labGrowth;\n return {...st,spread:labGrowth,reach,follow,upper:reach,lower:reach,upperMass:follow,lowerMass:follow,release:labRelease,lo:.5-.499*reach,hi:.5+.499*reach,motion:follow*2,active:1-follow};\n};\nfunction labAt(t){elapsed=t;const local=((t%labTiming.total)+labTiming.total)%labTiming.total;\n const grow=Math.max(0,Math.min(1,local/labTiming.formed));\n const release=Math.max(0,Math.min(1,(local-labTiming.formed-labTiming.hold)/labTiming.recovery));\n labRelease=release*release*(3-2*release);\n const u=grow*grow*(3-2*grow);labGrowth=u*(1-labRelease);draw();\n}\nreturn {canvas,timing:labTiming,at:labAt,atPhase(grow,hold,recover){\n const t=grow<1?grow*labTiming.formed:recover>0?labTiming.formed+labTiming.hold+recover*labTiming.recovery:labTiming.formed+hold*labTiming.hold;\n labAt(t);\n},duration:labTiming.total,formed:labTiming.formed+.1};\n","nodes":{"distanceVal":{"value":"0","checked":false},"distance":{"value":"40","checked":false},"reachVal":{"value":"0","checked":false},"reach":{"value":"50","checked":false},"amountVal":{"value":"0","checked":false},"amount":{"value":"50","checked":false},"followVal":{"value":"0","checked":false},"follow":{"value":"50","checked":false},"cleft":{"value":"0","checked":false},"flow":{"value":"0","checked":true},"surface":{"value":"0","checked":true},"mesh":{"value":"0","checked":true},"guide":{"value":"0","checked":false},"timelineVal":{"value":"0","checked":false},"timeline":{"value":"0","checked":false},"variation":{"value":"0","checked":false},"seedLabel":{"value":"0","checked":false},"pause":{"value":"0","checked":false},"reset":{"value":"0","checked":false},"save":{"value":"0","checked":false},"phase":{"value":"0","checked":false},"cycle":{"value":"0","checked":false}}},"B":{"code":"\n\n'use strict';\n// One-body deformation: local reach leads the same membrane into B.\n// The outer rim reaches locally; the connected membrane follows.\n// All contour vertices move throughout formation and recovery.\nconst REFERENCE={\"curves\":[[[-153.0,222.0],[-139.0,145.0],[-100.0,75.0],[-78.0,-10.0]],[[-78.0,-10.0],[-58.0,-86.0],[-32.0,-177.0],[-12.0,-214.0]],[[-12.0,-214.0],[22.0,-168.0],[48.0,-87.0],[76.0,-10.0]],[[76.0,-10.0],[107.0,65.0],[138.0,151.0],[157.0,217.0]]]};\nconst canvas=document.querySelector('#dish'),ctx=canvas.getContext('2d'),TAU=Math.PI*2;\n// Match the canvas backing to its actual displayed size and device pixels.\n// Draw all geometry in the original 900-unit coordinate system.\nlet pixelScale=1;\nfunction syncCanvasResolution(){\n const cssWidth=typeof canvas.getBoundingClientRect==='function'?canvas.getBoundingClientRect().width:900;\n const dpr=typeof window==='undefined'?1:(window.devicePixelRatio||1);\n const backing=Math.max(1,Math.min(4096,Math.round((cssWidth||900)*dpr)));\n if(canvas.width!==backing||canvas.height!==backing){canvas.width=backing;canvas.height=backing}\n pixelScale=backing/900;\n ctx.setTransform(pixelScale,0,0,pixelScale,0,0);\n ctx.imageSmoothingEnabled=false;\n}\nsyncCanvasResolution();\nconst ids=['distance','reach','amount','follow'],controls=Object.fromEntries(ids.map(id=>[id,document.getElementById(id)]));\nconst presets=[[40,50,50,50],[58,85,50,50],[40,50,90,85],[58,85,90,85]];\nlet seed=1,elapsed=0,paused=false,last=0,grain=[[],[],[]],guide=[],length=0;\nfunction mix(a,b,t){return a+(b-a)*t}\nfunction smooth(t){t=Math.max(0,Math.min(1,t));return t*t*t*(t*(t*6-15)+10)}\nfunction hash(x,y){const n=Math.sin(x*127.1+y*311.7+seed*53.13)*43758.5453;return n-Math.floor(n)}\nfunction cubic(a,b,c,d,t){const u=1-t;return {x:u*u*u*a.x+3*u*u*t*b.x+3*u*t*t*c.x+t*t*t*d.x,y:u*u*u*a.y+3*u*u*t*b.y+3*u*t*t*c.y+t*t*t*d.y}}\nfunction generate(){\n guide=[];length=0;grain=[[],[],[]];\n const curves=REFERENCE.curves.map(c=>c.map(p=>({x:p[0],y:p[1]})));\n for(let k=0;k<curves.length;k++)for(let j=k?1:0;j<=100;j++){\n  const p=cubic(...curves[k],j/100),prev=guide[guide.length-1];\n  if(prev)length+=Math.hypot(p.x-prev.x,p.y-prev.y);\n  guide.push({...p,s:length});\n }\n for(let i=0;i<15000;i++){\n  grain[i%3].push({angle:hash(i,20)*TAU,rho:Math.sqrt(hash(i,21)),r:.36+hash(i,22)*.62});\n }\n document.querySelector('#seedLabel').textContent='B01 \u00b7 GUIDED MEMBRANE '+seed;\n}\nfunction sample(u,st){\n const distance=Math.max(0,Math.min(1,u))*length;let lo=0,hi=guide.length-1;\n while(lo+1<hi){const mid=(lo+hi)>>1;if(guide[mid].s<distance)lo=mid;else hi=mid}\n const a=guide[lo],b=guide[hi],t=(distance-a.s)/(b.s-a.s||1);\n const dx=b.x-a.x,dy=b.y-a.y,n=Math.hypot(dx,dy)||1;\n // The old code's curved guides are kept subtle and tied to body progress.\n const wave=document.querySelector('#flow').checked?2*Math.sin(Math.PI*u)*Math.sin(u*7+st.motion)*st.active:0;\n return {x:mix(a.x,b.x,t)-dy/n*wave,y:mix(a.y,b.y,t)+dx/n*wave,nx:-dy/n,ny:dx/n};\n}\n// Overlapping reach and follow rhythms with a gradual landing.\n// Both stages overlap; there is no intermediate stop at the membrane shape.\n// Brief forceful takeoff, followed by a long release of tension.\n// Follow carries less of the initial burst, so tissue catches up behind reach.\nconst paceCurves=[0,1].map(branch=>{\n const values=[0];let total=0;\n for(let i=1;i<=384;i++){\n  const t=(i-.5)/384;\n  const decay=branch===0?7.2:4.5;\n  const takeoff=branch===0?.16:.20;\n  const velocity=smooth(t/takeoff)*(.060+Math.exp(-decay*t))*smooth((1-t)/.28);\n  total+=Math.pow(velocity,1.28);values.push(total);\n }\n return values.map(v=>v/total);\n});\nfunction flowingProgress(t,branch){\n t=Math.max(0,Math.min(1,t));const curve=paceCurves[branch],p=t*384,i=Math.floor(p);\n return i>=384?1:mix(curve[i],curve[i+1],p-i);\n}\nconst introPaceCurves=[0,1].map(()=>{\n const values=[0];let total=0;\n for(let i=1;i<=384;i++){\n  const t=(i-.5)/384;\n  // Build momentum, then maintain a steady faster pace into the handoff.\n  const velocity=smooth(t/.52)*(.22+.78*smooth(t/.46))*smooth((1-t)/.27);\n  total+=Math.pow(velocity,1.28);values.push(total);\n }\n return values.map(v=>v/total);\n});\nfunction introProgress(t,branch){\n t=Math.max(0,Math.min(1,t));const curve=introPaceCurves[branch],p=t*384,i=Math.floor(p);\n return i>=384?1:mix(curve[i],curve[i+1],p-i);\n}\n// Recovery gathers momentum rather than easing equally at both ends.\nconst returnPace=(()=>{\n const values=[0];let total=0;\n for(let i=1;i<=384;i++){\n  const t=(i-.5)/384;\n  const velocity=(.045+4.8*t*t*t)*smooth(t/.10)*smooth((1-t)/.065);\n  total+=Math.pow(velocity,1.28);\n  values.push(total);\n }\n return values.map(v=>v/total);\n})();\nfunction recoveryProgress(t){\n const p=Math.max(0,Math.min(1,t))*384,i=Math.floor(p);\n return i>=384?1:mix(returnPace[i],returnPace[i+1],p-i);\n}\nfunction timing(){\n const rd=1.28*(5.0-(+controls.reach.value)*.021);\n const fd=Math.max(rd*.96,1.28*(4.8-(+controls.follow.value)*.020));\n const lag=.34+(+controls.distance.value)*.003;\n const intro=2.4,startA=intro*.74,formed=startA+Math.max(rd,lag+fd),hold=2.75,recovery=8;\n return {rd,fd,la