// continuously instead of only changing the clock of the growth front.\nfunction targetFieldAt(x,y){\n const f=MATERIAL_FIELD,fx=Math.max(0,Math.min(f.nx-1.001,(x-f.x0)/f.step)),fy=Math.max(0,Math.min(f.ny-1.001,(y-f.y0)/f.step));\n const ix=Math.floor(fx),iy=Math.floor(fy),tx=fx-ix,ty=fy-iy,k=iy*f.nx+ix;\n return mix(mix(fieldTarget[k],fieldTarget[k+1],tx),mix(fieldTarget[k+f.nx],fieldTarget[k+f.nx+1],tx),ty)/16;\n}\nfunction growMaterialField(st){\n fieldVersion++;\n const nx=MATERIAL_FIELD.nx,ny=MATERIAL_FIELD.ny,step=MATERIAL_FIELD.step;\n const tissue=guide.map(p=>tissueAt(p.s/length,st));\n const first=sample(st.lo,st),last=sample(st.hi,st);\n const showHoles=document.querySelector('#mesh').checked;\n const heart=sample(.5-.20*st.upperMass*(1-st.lowerMass)+.16*st.lowerMass,st);\n const seed=26*(1-Math.min(st.upperMass,st.lowerMass));\n const tailSettle=smoother((st.t-(st.formed-2.0))/2.0);\n const tailFrame=sample(.998,st);\n const tailOffset=10*(1-tailSettle)*(1-st.release);\n for(let y=0;y<ny;y++)for(let x=0;x<nx;x++){\n  const i=y*nx+x,k=fieldIndex[i],u=guide[k].s/length,material=tissue[k];\n  const px=MATERIAL_FIELD.x0+x*step,py=MATERIAL_FIELD.y0+y*step;\n  let d=fieldDistance[i]/16;\n  if(u<st.lo)d=Math.hypot(px-first.x,py-first.y);\n  else if(u>st.hi)d=Math.hypot(px-last.x,py-last.y);\n  let body=Math.min(48,material.radius)-d;\n  // Early ribs/openings belong to the reaching material itself.\n  const along=fieldAlong[i]/16,cross=fieldCross[i]/16;\n  const gap=((along+6.5)%13+13)%13-6.5;\n  const opening=material.bone;\n  if(opening>.01&&showHoles){\n   const hole=((gap/2.7)**2+(cross/(6.3*opening))**2-1)*3;\n   body=Math.min(body,hole);\n  }\n  const settling=smoother((material.fill-.18)/.82);\n  // Stationary local sites open/tighten rather than travel across the body.\n  // Smooth strain changes the negative spaces and the thickness between them.\n  const phase=st.livePhase;\n  const porePulse=Math.sin(phase*1.5)*Math.sin(px*.037+py*.021)+\n   .55*Ma